/* se11-create-entries — SE11 Create Entries 손입력 훈련기 엔진.
   config = window.CE_CFG { table, key:['DAN','MUL'], clients:['100','200'], seed:[{client,dan,mul,result}] }.
   저장: 키(현재 client+DAN+MUL) 중복이면 거부. RESULT != DAN*MUL 이면 저장은 되나 경고(값 미검증).
   클라이언트 칩 전환 → 그 client 행만 보임(MANDT 분리). Table Contents 표시.
   seed는 선택 — 비우면 빈 테이블에서 시작한다(키 중복 실험을 학습자가 직접 만들어 겪게).
   #ce-reset 버튼이 있으면 '처음으로'(seed 상태 복원) 연결. */
(function () {
  var cfg;
  try { cfg = JSON.parse(document.getElementById('ce-cfg').textContent); }
  catch (e) { cfg = { table: 'ZTABLE', clients: ['100', '200'], seed: [] }; }
  var clients = cfg.clients || ['100', '200'];
  var cur = clients[0];
  var rows = seedRows();   // seed 없으면 빈 테이블에서 시작(레슨 서술과 동일)

  var $ = function (id) { return document.getElementById(id); };
  var iDan = $('ce-dan'), iMul = $('ce-mul'), iRes = $('ce-res'),
      elMsg = $('ce-msg'), elTbl = $('ce-tbl'), elCnt = $('ce-cnt'), elChips = $('ce-clients');

  function renderChips() {
    elChips.innerHTML = clients.map(function (c) {
      return '<button class="ce__cchip' + (c === cur ? ' on' : '') + '" data-c="' + c + '">MANDT ' + c + '</button>';
    }).join('');
    elChips.querySelectorAll('.ce__cchip').forEach(function (b) {
      b.addEventListener('click', function () { cur = b.dataset.c; renderChips(); renderTable(); msg('idle', '클라이언트 ' + cur + '로 전환 — 이 방(client)에 넣은 행만 보입니다.'); });
    });
  }

  function curRows() { return rows.filter(function (r) { return r.client === cur; }); }

  function renderTable(newKey) {
    var rs = curRows();
    elCnt.textContent = rs.length + '행';
    if (!rs.length) { elTbl.innerHTML = ''; $('ce-empty').style.display = 'block'; return; }
    $('ce-empty').style.display = 'none';
    var body = rs.map(function (r) {
      var wrong = r.result !== r.dan * r.mul;
      var isNew = newKey && (r.dan + 'x' + r.mul) === newKey;
      return '<tr class="' + (wrong ? 'bad-calc ' : '') + (isNew ? 'new' : '') + '">' +
        '<td class="mandt">' + r.client + '</td><td>' + r.dan + '</td><td>' + r.mul + '</td>' +
        '<td class="res">' + r.result + '</td></tr>';
    }).join('');
    elTbl.innerHTML = '<thead><tr><th>MANDT</th><th>DAN</th><th>MUL</th><th>RESULT</th></tr></thead><tbody>' + body + '</tbody>';
  }

  function msg(level, text) {
    elMsg.innerHTML = '<span class="' + level + '"><span class="ico">' +
      (level === 'bad' ? '✕' : level === 'warn' ? '⚠' : level === 'ok' ? '✔' : '·') + '</span>' + text + '</span>';
  }

  function save() {
    var d = parseInt(iDan.value, 10), m = parseInt(iMul.value, 10), r = parseInt(iRes.value, 10);
    if (isNaN(d) || isNaN(m) || isNaN(r)) { msg('bad', 'DAN·MUL·RESULT를 모두 숫자로 입력하세요.'); return; }
    var dup = rows.some(function (x) { return x.client === cur && x.dan === d && x.mul === m; });
    if (dup) { msg('bad', '저장 실패: 같은 키 조합(MANDT ' + cur + ' + DAN ' + d + ' + MUL ' + m + ')이 이미 있습니다. 키는 중복될 수 없습니다.'); return; }
    rows.push({ client: cur, dan: d, mul: m, result: r });
    renderTable(d + 'x' + m);
    if (r !== d * m) {
      msg('warn', '저장됨 — 하지만 ' + d + '×' + m + ' = ' + (d * m) + '인데 RESULT=' + r + '. 키는 중복만 막을 뿐, 계산이 맞는지는 검증하지 않습니다(빨간 행).');
    } else {
      msg('ok', '저장됨: ' + d + ' × ' + m + ' = ' + r + ' (MANDT ' + cur + ').');
    }
    iDan.value = ''; iMul.value = ''; iRes.value = ''; iDan.focus();
    post();
  }

  function fill2and3() {
    // 2단·3단을 현재 client에 자동 채움(이미 있으면 건너뜀)
    var added = 0;
    [2, 3].forEach(function (dan) {
      for (var mul = 1; mul <= 9; mul++) {
        if (!rows.some(function (x) { return x.client === cur && x.dan === dan && x.mul === mul; })) {
          rows.push({ client: cur, dan: dan, mul: mul, result: dan * mul }); added++;
        }
      }
    });
    renderTable();
    msg(added ? 'ok' : 'idle', added ? ('2단·3단 ' + added + '행을 한 번에 채웠습니다(총 18행). 손으로 하면 지치죠?') : '이미 다 채워져 있습니다.');
    post();
  }

  function seedRows() {
    return (cfg.seed || []).map(function (r) { return { client: String(r.client), dan: +r.dan, mul: +r.mul, result: +r.result }; });
  }

  // 처음으로 — seed 상태(보통 빈 테이블)로 되돌린다. 실험을 몇 번이든 다시 할 수 있게.
  function reset() {
    rows = seedRows();
    cur = clients[0];
    iDan.value = ''; iMul.value = ''; iRes.value = '';
    renderChips(); renderTable();
    msg('idle', '처음으로 되돌렸습니다 — 빈 테이블에서 다시 시작해 보세요.');
    post();
  }

  function post() { try { if (document.documentElement.clientWidth < 60) return; var el = document.querySelector('.wrap'); var h = Math.ceil(el ? el.getBoundingClientRect().height : document.body.scrollHeight) + 6; parent.postMessage({ sda: 'embed-height', h: h }, '*'); } catch (e) {} }

  $('ce-save').addEventListener('click', save);
  var fb = $('ce-fill'); if (fb) fb.addEventListener('click', fill2and3);
  var rb = $('ce-reset'); if (rb) rb.addEventListener('click', reset);
  [iDan, iMul, iRes].forEach(function (i) { i.addEventListener('keydown', function (e) { if (e.key === 'Enter') save(); }); });
  renderChips(); renderTable(); msg('idle', 'DAN·MUL·RESULT를 넣고 저장해 보세요. 같은 키를 두 번 넣거나, 계산이 틀린 값을 넣어 보세요.');
  window.addEventListener('load', post); window.addEventListener('resize', post); post();
})();

FILE: C:\SAP\sap-dev-academy\embeds\_engine\type-borrow-lab.js
/* ===== type-borrow-lab 엔진 JS — 선언 2축 실험(모양을 어디서 빌려 오나 × 몇 건을 담나) =====
   ① 모양 출처 세그(로컬 타입 ↔ DB 테이블) → 필드 구성이 바뀐다(딸려 오는 필드는 .extra로 표시)
   ② 개수 세그(TYPE ↔ TYPE TABLE OF) → 한 건 ↔ 여러 건으로 갈린다(변수 이름도 함께)
   고른 조합으로 DATA 선언 한 줄을 만들고, 그 변수가 메모리에 잡히는 모양을 그린다. 판정은 항상 표시.
   설정 = window.TBLAB_CFG {
     hd, lead, srcLabel, cntLabel,
     sources:[{key, btn, type, fields:[{n, extra?}], note?}],
     counts:[{key, btn, kw, varName, rows, cmt, shapeCap}],
     verdict, caution:{<sourceKey>: html}   // caution = 그 출처를 골랐을 때만 덧붙는 주의(신뢰된 HTML)
   }
   ⚠️ 조각 엔진 — .wrap/.hd/.lead/.note는 주 엔진 CSS 몫(호스트 위젯의 data-eng는 주 엔진 유지). */
(function () {
  var cfg = window.TBLAB_CFG; if (!cfg) return;
  var root = document.querySelector('[data-tb]'); if (!root) return;
  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

  var sources = cfg.sources || [], counts = cfg.counts || [];
  var srcKey = sources.length ? sources[0].key : '', cntKey = counts.length ? counts[0].key : '';
  function pick(list, key) { for (var i = 0; i < list.length; i++) { if (list[i].key === key) return list[i]; } return list[0]; }

  function seg(axisLabel, list, curKey, attr) {
    var h = '<div class="tb-axis"><span class="tb-axis__lab">' + esc(axisLabel) + '</span><div class="tb-seg">';
    list.forEach(function (o) {
      h += '<button type="button" class="tb-seg__b' + (o.key === curKey ? ' on' : '') + '" '
        + attr + '="' + esc(o.key) + '">' + esc(o.btn) + '</button>';
    });
    return h + '</div></div>';
  }

  function render() {
    var s = pick(sources, srcKey), c = pick(counts, cntKey);
    var h = '';
    if (cfg.hd) h += '<p class="tb-hd">' + cfg.hd + '</p>';
    if (cfg.lead) h += '<p class="tb-lead">' + cfg.lead + '</p>';
    h += seg(cfg.srcLabel || '모양 출처', sources, srcKey, 'data-src');
    h += seg(cfg.cntLabel || '담는 개수', counts, cntKey, 'data-cnt');

    // 만들어진 선언 한 줄
    h += '<code class="tb-decl">DATA <b>' + esc(c.varName) + '</b> ' + esc(c.kw) + ' <b>' + esc(s.type) +
         '</b>.' + (c.cmt ? '   <span class="cmt">" ' + esc(c.cmt) + '</span>' : '') + '</code>';

    // 메모리에 잡히는 모양
    var fields = s.fields || [];
    h += '<div class="tb-shape"><div class="tb-shape__cap">' + esc(c.shapeCap || '메모리에 잡히는 모양') +
         ' — 필드 <span class="n">' + fields.length + '개</span></div><div class="tb-rows">';
    var many = (c.rows || 1) > 1, draw = Math.min(c.rows || 1, 3);
    for (var i = 0; i < draw; i++) {
      // 여러 건일 때 라벨은 '1행·2행…' — gt[ ] 같은 표기는 뒤 챕터 문법이라 쓰지 않는다(R6 게이팅)
      h += '<div class="tb-row"><span class="tb-row__n">' + (many ? (i + 1) + '행' : esc(c.varName)) +
           '</span><span class="tb-cells">';
      fields.forEach(function (f) { h += '<i' + (f.extra ? ' class="extra"' : '') + '>' + esc(f.n) + '</i>'; });
      h += '</span></div>';
    }
    if ((c.rows || 1) > draw) h += '<div class="tb-etc">⋮ 같은 모양으로 계속 쌓인다</div>';
    h += '</div></div>';

    // 판정 — 어느 조합이든 메모리라는 사실 + 출처별 주의
    h += '<div class="tb-verdict">' + (cfg.verdict || '');
    var caution = (cfg.caution || {})[s.key];
    if (caution) h += '<span class="caution">' + caution + '</span>';
    h += '</div>';
    root.innerHTML = h;
  }

  root.addEventListener('click', function (e) {
    var b = e.target.closest('[data-src]');
    if (b) { srcKey = b.getAttribute('data-src'); render(); return; }
    b = e.target.closest('[data-cnt]');
    if (b) { cntKey = b.getAttribute('data-cnt'); render(); }
  });
  render();
})();

